// Import of required libraries
import { test, expect, SkyrampClient } from '@skyramp/skyramp';
import {
    createCollection,
    deleteCollection,
    deleteCollectionMember,
    getCollectionMembers,
    resolveUserId,
    updateCollection,
} from './skyrampUtils';

// A user id no account in the database can hold, used as the removal target that is not a member.
const NOT_A_MEMBER_USER_ID = 999999999;

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();

    const { userId: memberUserId, usersPostResponse } = await resolveUserId(client);
    // The account this test adds and removes is registered on the first run and
    // already present on every later one; both outcomes are asserted for what they are.
    if (usersPostResponse.statusCode === 400) {
        expect(JSON.parse(usersPostResponse.responseBody).response, 'the secondary account is already registered')
            .toBe("Email or Username already exists.");
    } else {
        expect(usersPostResponse.statusCode, 'status code').toBe(201);
    }
    const collectionName = `member-removal-${Date.now()}`;

    const collectionsPostResponse = await createCollection(client, collectionName);
    expect(collectionsPostResponse.statusCode, 'status code').toBe(200);
    const createdCollection = JSON.parse(collectionsPostResponse.responseBody).response;
    const collectionId = Number(createdCollection.id);
    expect(Number.isInteger(collectionId), 'the created collection carries a numeric id').toBe(true);
    expect(createdCollection.name, 'the created collection name').toBe(collectionName);
    expect(createdCollection.color, 'color echoes the value the request sent').toBe("#0ea5e9");
    expect(createdCollection.isPublic, 'isPublic echoes the value the request sent').toBe(false);
    expect(collectionId, 'the collection id the server assigned').toBeGreaterThan(0);
    expect(createdCollection.createdAt, 'createdAt is an ISO timestamp').toMatch(/^\d{4}-\d{2}-\d{2}T/);

    const collectionsCollectionsPutResponse = await updateCollection(client, collectionId, collectionName, [
        { canCreate: false, canDelete: false, canUpdate: false, userId: memberUserId },
    ]);
    expect(collectionsCollectionsPutResponse.statusCode, 'status code').toBe(200);

    // Remove the account that really is a member of this collection.
    const membersDeleteResponse = await deleteCollectionMember(client, collectionId, memberUserId);
    expect(membersDeleteResponse.statusCode, 'status code').toBe(200);
    expect(JSON.parse(membersDeleteResponse.responseBody).response, 'removing a real member reports the removal')
        .toBe("Member removed.");

    const membersGetResponse = await getCollectionMembers(client, collectionId);
    expect(membersGetResponse.statusCode, 'status code').toBe(200);
    const membersAfterRemoval = JSON.parse(membersGetResponse.responseBody).response;
    expect(membersAfterRemoval, 'the removed member is gone from the collection').toEqual([]);
    expect(membersAfterRemoval.length, 'the collection has no members left').toBe(0);
    expect(membersAfterRemoval[0], 'the collection has no first member').toBeUndefined();

    // The same call for a user id that is not a member of this collection.
    try {
        const membersDelete1Response = await deleteCollectionMember(
            client, collectionId, NOT_A_MEMBER_USER_ID, 404,
        );
        expect(membersDelete1Response.statusCode, 'status code').toBe(404);
        // Removing a user the collection does not have is not a removal. The handler answers
        // 404 for the collection's own missing record ("Collection not found."), and a member
        // named by an id the collection does not hold is the same kind of miss.
        expect(JSON.parse(membersDelete1Response.responseBody).response,
            'the response body for a removal that matched nothing')
            .not.toBe("Member removed.");
    } finally {
        // Runs whether the assertions above pass or fail, so the collection this test created
        // is always removed.
        const collectionsCollectionsDeleteResponse = await deleteCollection(client, collectionId);
        expect(collectionsCollectionsDeleteResponse.statusCode, 'status code').toBe(200);
    }
});
